using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace ResearchAgent;

/// <summary>
/// Simulated web search tool. Replace with a real search API (Bing, Google, Tavily) for production use.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    public static async Task<string> SearchAsync(string query)
    {
        // Check if a real search API key is configured
        var tavilyKey = Environment.GetEnvironmentVariable("TAVILY_API_KEY");
        if (!string.IsNullOrEmpty(tavilyKey))
        {
            return await SearchWithTavilyAsync(query, tavilyKey);
        }

        // Fallback: simulated search results for demonstration
        return GetSimulatedResults(query);
    }

    private static async Task<string> SearchWithTavilyAsync(string query, string apiKey)
    {
        var request = new { api_key = apiKey, query, max_results = 5 };
        var response = await HttpClient.PostAsJsonAsync("https://api.tavily.com/search", request);
        response.EnsureSuccessStatusCode();

        var result = await response.Content.ReadFromJsonAsync<TavilyResponse>();
        if (result?.Results is null || result.Results.Count == 0)
            return "No results found.";

        return string.Join("\n\n", result.Results.Select(r =>
            $"**{r.Title}**\nSource: {r.Url}\n{r.Content}"));
    }

    private static string GetSimulatedResults(string query)
    {
        return $"""
            [Simulated search results for: "{query}"]

            Result 1: Overview of {query}
            Source: https://example.com/overview
            This is a comprehensive overview covering the key aspects of {query}. 
            The topic encompasses multiple areas of study and has significant real-world applications.

            Result 2: Recent developments in {query}
            Source: https://example.com/recent
            Recent research has shown new developments in {query}, including advances 
            in methodology and novel applications discovered in the past year.

            Result 3: Expert analysis of {query}
            Source: https://example.com/analysis
            Experts note that {query} continues to evolve rapidly, with implications 
            for both industry and academia. Key challenges remain in scalability and adoption.

            Note: These are simulated results. Set the TAVILY_API_KEY environment variable for real web search.
            """;
    }

    private sealed class TavilyResponse
    {
        [JsonPropertyName("results")]
        public List<TavilyResult> Results { get; set; } = [];
    }

    private sealed class TavilyResult
    {
        [JsonPropertyName("title")]
        public string Title { get; set; } = "";

        [JsonPropertyName("url")]
        public string Url { get; set; } = "";

        [JsonPropertyName("content")]
        public string Content { get; set; } = "";
    }
}

namespace ResearchAgent;

public sealed class NoteService
{
    private readonly List<ResearchNote> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add(new ResearchNote(title, content, DateTime.UtcNow));
    }

    public IReadOnlyList<ResearchNote> GetAllNotes() => _notes.AsReadOnly();

    public void Clear() => _notes.Clear();
}

public sealed record ResearchNote(string Title, string Content, DateTime CreatedAt);

