using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            Console.WriteLine($"  [Searching web for: \"{query}\"]");
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a given query. Returns a list of relevant snippets."),

    AIFunctionFactory.Create(
        (string title, string content) =>
        {
            Console.WriteLine($"  [Saving note: \"{title}\"]");
            noteService.AddNote(title, content);
            return $"Note saved: {title}";
        },
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            Console.WriteLine("  [Reading all notes]");
            return noteService.GetAllNotes();
        },
        "read_notes",
        "Reads all saved research notes."),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic, you:
        1. Search the web for relevant information (perform multiple searches to cover different angles)
        2. Save important findings as notes
        3. Read your notes and produce a comprehensive summary

        Always search for at least 2-3 different aspects of the topic before summarizing.
        Save key findings as notes before writing the final summary.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools.",
    tools: tools);

Console.WriteLine("Research Agent Starting...");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine(response.Text);

Console.WriteLine("\n\n--- Research Notes ---");
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"\n## {note.Title}\n{note.Content}");
}

